import{_ as i,l as n,o as e,c as l,v as r,p,x as t,d as s,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"多项式归约","description":"","frontmatter":{"title":"多项式归约","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/np-reduction.md","filePath":"cs/np-reduction.md","lastUpdated":1789023840000}'),c={name:"cs/np-reduction.md"};function h(_,a,B,P,f,u){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="多项式归约" tabindex="-1">多项式归约 <a class="header-anchor" href="#多项式归约" aria-label="Permalink to &quot;多项式归约&quot;">​</a></h1><div class="epigraph"><p>若 $A$ 可多项式变成 $B$ 的实例，则 $B$ 的多项式算法会带走 $A$；难度沿箭头向上游传。</p><footer>—— 据 Karp, Reducibility Among Combinatorial Problems, 1972；Garey and Johnson, 1979 整理</footer></div><p>上一课<a href="/cs/p-vs-np">P 与 NP</a>钉了两类判定。本课不重定义证书。缺口是：如何在问题之间<strong>传递</strong>「若这个易则那个易」。多项式时间多一归约（Karp）：\\(f\\) 多项式可计算，\\(x\\in A\\iff f(x)\\in B\\)。本课只钉这条箭头的方向与用法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>独立地证明每个问题都难，没有公共杠杆。归约说：解 \\(B\\) 的黑盒足够解 \\(A\\)。因此若 \\(A\\) 被认为难而 \\(A\\le_p B\\)，则 \\(B\\) 至少一样难。方向容易画反：把 \\(B\\) 化成 \\(A\\) 证明的是 \\(A\\) 更难。缺口是把箭头画对，不是再讲 NP 是什么。</p><p>Cook 归约允许对 \\(B\\) 的多次自适应询问；本课主干用 Karp 多一映射，足够后课 NPC。不回到图灵机带子。</p><h3 id="归约不是「特例」" tabindex="-1">归约不是「特例」 <a class="header-anchor" href="#归约不是「特例」" aria-label="Permalink to &quot;归约不是「特例」&quot;">​</a></h3><p>独立集不是团的别名；但互补图把一个实例多项式变成另一个。那是归约，不是同一问题。背包化成子集和是「限制参数」，也要写成显式 \\(f\\)。</p><p><span class="marginnote">Karp 1972 的 21 个问题靠一串 \\(\\le_p\\)。Garey/Johnson 强调：证明 \\(B\\) 难，从已知难的 \\(A\\) 化到 \\(B\\)。本课后课 SAT 出发，这里只练方向。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定 \\(A,B\\)，构造 \\(f\\)：写清输入如何改写、为何多项式、为何是当且仅当。验证器不出现在 \\(f\\) 里；\\(f\\) 是实例到实例。传递性：\\(A\\le_p B\\le_p C\\) 则 \\(A\\le_p C\\)。</p>',11)),(e(),p(A,null,{default:t(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%97%AE%E9%A2%98%20A%22%5D%20--%3E%7C%22f%20%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%7C%20B%5B%22%E9%97%AE%E9%A2%98%20B%22%5D%0A%20%20B%20--%3E%20ALG%5B%22%E8%8B%A5%20B%E2%88%88P%22%5D%0A%20%20ALG%20--%3E%20AP%5B%22%E5%88%99%20A%E2%88%88P%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>若 \\(B\\in P\\) 且 \\(A\\le_p B\\) 则 \\(A\\in P\\)。若 \\(A\\) 不在 P（相对假设）且 \\(A\\le_p B\\) 则 \\(B\\) 不在 P。NPC 定义下一课才用「NP 中且万物化到它」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>P 在 Karp 归约下关闭：归约加算法仍多项式。NP 同样关闭。这保证完全问题若在 P 则 \\(P=NP\\)。本课把这句话留给下一课的定义落地。</p><p>不要用指数时间的 \\(f\\)：那不保持多项式类。也不要把近似比的归约（L-reduction）提前引进。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 SAT 完全，不列出 21 题。不处理空间归约、计数归约。后课默认：证明「至少一样难」用 \\(A\\le_p B\\)，\\(A\\) 已知难，\\(B\\) 是新问题。典型 NPC 清单是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(A\\le_p B\\)：\\(A\\) 的实例多项式变成 \\(B\\) 的实例，是当且仅当。</li><li>难度沿箭头向上游；\\(B\\) 易则 \\(A\\) 易。</li><li>画反箭头就证错对象。</li><li>出处：Karp, 1972；Garey and Johnson, 1979。</li></ul>',8))])}const b=i(c,[["render",h]]);export{E as __pageData,b as default};
